package co.serviasigna.domain;

import jakarta.persistence.*;
import java.time.LocalDateTime;

/**
 * Cliente que recibe los pedidos (tabla CLIENTE, RF-M2-04). No tiene acceso al sistema.
 * <p>
 * EN: Customer who receives the orders (CLIENTE table, RF-M2-04). It has no access to the system.
 */
@Entity
@Table(name = "CLIENTE")
public class Customer {
    /** El identificador que genera Oracle. EN: The identifier generated by Oracle. */
    @Id @GeneratedValue(strategy = GenerationType.IDENTITY) private Long id;
    /** El nombre del cliente. EN: The customer name. */
    @Column(name = "NOMBRE", nullable = false, length = 80) private String name;
    /** El teléfono (único). EN: The phone (unique). */
    @Column(name = "TELEFONO", nullable = false, length = 20, unique = true) private String phone;
    /** Si el cliente está activo. EN: Whether the customer is active. */
    @Column(name = "ACTIVO", nullable = false) private boolean active = true;
    /** La fecha de registro. EN: The registration date. */
    @Column(name = "CREADO", nullable = false) private LocalDateTime created = LocalDateTime.now();

    /**
     * Constructor vacío que exige JPA para leer la fila de la base de datos.
     * <p>
     * EN: Empty constructor required by JPA to read the row from the database.
     */
    protected Customer() {}

    /**
     * Crea un cliente activo.
     * <p>
     * EN: Creates an active customer.
     *
     * @param name nombre / name
     * @param phone teléfono, único / phone, unique
     */
    public Customer(String name, String phone) { this.name = name; this.phone = phone; }

    /**
     * Cambia el nombre y el teléfono.
     * <p>
     * EN: Changes the name and the phone.
     *
     * @param name nuevo nombre / new name
     * @param phone nuevo teléfono / new phone
     */
    public void update(String name, String phone) { this.name = name; this.phone = phone; }

    /**
     * Cambia si el cliente está activo.
     * <p>
     * EN: Changes whether the customer is active.
     *
     * @param a el nuevo valor / the new value
     */
    public void setActive(boolean a) { active = a; }

    /**
     * Devuelve el identificador que genera Oracle.
     * <p>
     * EN: Returns the identifier generated by Oracle.
     *
     * @return el identificador que genera Oracle / the identifier generated by Oracle
     */
    public Long getId() { return id; }

    /**
     * Devuelve el nombre del cliente.
     * <p>
     * EN: Returns the customer name.
     *
     * @return el nombre del cliente / the customer name
     */
    public String getName() { return name; }

    /**
     * Devuelve el teléfono (único).
     * <p>
     * EN: Returns the phone (unique).
     *
     * @return el teléfono (único) / the phone (unique)
     */
    public String getPhone() { return phone; }

    /**
     * Indica si el cliente está activo.
     * <p>
     * EN: Tells whether the customer is active.
     *
     * @return true si se cumple / true if it applies
     */
    public boolean isActive() { return active; }

    /**
     * Devuelve la fecha de registro.
     * <p>
     * EN: Returns the registration date.
     *
     * @return la fecha de registro / the registration date
     */
    public LocalDateTime getCreated() { return created; }
}
